<?php
/** TEMP PS S1685 no — DEPLOY petshop-planas-langas.php v1.0.1 (rugsėjo norma pro rata nuo 120/ketv.); bak, token_get_all, heartbeat. */
add_action('init', function(){
  if (!isset($_GET['ps_s1685no'])) return; $o=array('v'=>'S1685 no'); $f=WPMU_PLUGIN_DIR.'/petshop-planas-langas.php'; copy($f,WP_CONTENT_DIR.'/uploads/ps-backups/petshop-planas-langas.php.bak_s1685');
  $np=base64_decode(''); if(md5($np)!=='31b4aa6fd0e5e56f40ec725cbbd1c2c9'){ $o['STOP']='md5'; echo json_encode($o); exit; } try { token_get_all($np, TOKEN_PARSE); } catch (Throwable $e) { $o['STOP']=$e->getMessage(); echo json_encode($o); exit; }
  file_put_contents($f,$np); if(function_exists('opcache_invalidate')) opcache_invalidate($f,true); $o['md5']=md5_file($f); $hb=wp_remote_get(home_url('/'),array('timeout'=>20,'sslverify'=>false)); $o['heartbeat']=is_wp_error($hb)?0:wp_remote_retrieve_response_code($hb);
  header('Content-Type: application/json; charset=utf-8'); echo json_encode($o); exit;
});
